// Shared raw Kubernetes-API-proxy helpers, factored out of
// tekton/useTektonPipelineRuns.ts once a second consumer (useAnalysisRuns.ts)
// needed the exact same "go straight at the generic proxy, not
// useCustomResources" mechanism - see that file's own comment for the full
// reasoning: useCustomResources(entity, [...]) resolves objects through the
// entity's `hangar.io/app=<name>` label-selector, and both Tekton
// PipelineRuns and Argo Rollouts' own AnalysisRun child resources are
// generated by their respective controllers without that label at all
// (confirmed live on both). Going straight at
// `/api/kubernetes/proxy/<k8s-api-path>` + a `Backstage-Kubernetes-Cluster`
// header - the same route kubernetesProxyApiRef.getPodLogs itself calls
// under the hood - sidesteps label-selector matching entirely.

export async function k8sProxyGet<T>(
  discoveryApi: { getBaseUrl(id: string): Promise<string> },
  fetchApi: { fetch: typeof fetch },
  clusterName: string,
  path: string,
): Promise<T> {
  const baseUrl = await discoveryApi.getBaseUrl('kubernetes');
  const res = await fetchApi.fetch(`${baseUrl}/proxy${path}`, {
    headers: { 'Backstage-Kubernetes-Cluster': clusterName },
  });
  if (!res.ok) {
    const body = await res.json().catch(() => undefined);
    throw new Error(body?.error?.message ?? body?.message ?? `request failed with ${res.status}`);
  }
  return res.json() as Promise<T>;
}

